package webui

// stylesClientLogin is the client-access panel and login page, plus the client-access drawer (v43) and compact-login image pass (v45).
// Each const holds one contiguous slice of the stylesheet; the global order is
// reassembled in styles_desktop_app.go. Keep every const byte-identical to the
// corresponding line range of the original single-const layout.
const stylesClientLogin = `.client-access{margin-top:12px;border:1px solid var(--line);border-radius:9px;background:var(--surface);box-shadow:var(--shadow);overflow:hidden}.client-access>header{min-height:68px;display:flex;align-items:center;justify-content:space-between;padding:12px 15px;border-bottom:1px solid var(--line)}.client-access>header h2{font-size:15px}.client-access>header small{display:block;color:var(--muted);font-size:9px}.client-host-form{display:grid;grid-template-columns:minmax(220px,1fr) minmax(220px,1fr) auto;align-items:end;gap:10px;padding:14px 15px}.client-host-form>label{font-size:9px;font-weight:700}.client-host-form input{width:100%;display:block;margin-top:4px}.client-host-form label>small{display:block;margin-top:3px;color:var(--muted);font-size:8px;font-weight:400}.client-access-note{margin:0 15px 14px;padding:8px;border-radius:6px;background:var(--amber-soft);color:var(--amber);font-size:9px}.client-access>.alert{margin:0 15px 14px}.client-share{margin:0 15px 12px;padding:11px;border:1px solid color-mix(in srgb,var(--accent) 28%,var(--line));border-radius:8px;background:var(--accent-soft)}.client-share>header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:8px}.client-share>header b,.client-share>header small{display:block}.client-share>header b{font-size:10px}.client-share>header small{color:var(--muted);font-size:8px}.client-share-control input{min-width:0;width:100%;font-family:ui-monospace,monospace}.client-share-control button{border-radius:0}.client-share-control button:last-child{border-radius:0 7px 7px 0;padding:0 12px;background:var(--accent);color:#fff}.client-parameters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1px;margin:0 15px 15px;border:1px solid var(--line);border-radius:8px;background:var(--line);overflow:hidden}.client-parameters>div{min-width:0;padding:9px;background:var(--surface)}.client-parameters>div>span:first-child{display:block;margin-bottom:4px;color:var(--muted);font-size:8px;font-weight:700}.client-parameters code{display:block;overflow:hidden;color:var(--ink-2);font-size:9px;text-overflow:ellipsis;white-space:nowrap}.client-parameters .secret-value-control{margin-top:0}.client-parameters input{height:34px;font-size:9px}.client-access-empty{display:flex;align-items:center;justify-content:center;flex-direction:column;min-height:110px;padding:20px;color:var(--muted);text-align:center}.client-access-empty b{color:var(--ink);font-size:11px}.client-access-empty span{margin-top:4px;font-size:9px}.stack-form{display:flex;flex-direction:column;gap:20px}.stack-form label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:700}.theme-toggle{width:40px;height:40px;border:1px solid var(--line);border-radius:8px;background:var(--surface)}.login-body{min-height:100vh;display:grid;place-items:center;padding:28px;background:#e9edf5}.login-theme-toggle{position:fixed;right:20px;top:20px}.login-shell{width:min(1050px,100%);min-height:620px;display:grid;grid-template-columns:1.12fr .88fr;border-radius:16px;background:var(--surface);box-shadow:0 35px 80px -40px rgba(20,24,38,.5);overflow:hidden}.login-story{display:flex;flex-direction:column;justify-content:space-between;padding:40px;background:#171922;color:#fff}.brand{display:flex;align-items:center;gap:9px}.brand strong,.brand small{display:block}.brand small{color:#aab0c0;font-size:9px}.login-message{margin:42px 0}.login-message h1{font-size:40px;line-height:1.18}.login-message h1 em{color:#a5a6ff;font-style:normal}.login-copy{margin-top:16px;color:#b8bdcb;line-height:1.75}.login-visual{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.login-visual>span{padding:12px;border:1px solid #333642;border-radius:8px;background:#20222b}.login-visual i{width:7px;height:7px;display:block;margin-bottom:10px;border-radius:50%;background:#35c69d}.login-visual b,.login-visual small{display:block}.login-visual b{font-size:10px}.login-visual small{color:#9299aa;font-size:8px}.login-card{display:flex;flex-direction:column;justify-content:center;padding:44px}.login-card-head{display:flex;gap:12px;margin-bottom:28px}.login-icon{width:44px;height:44px;display:grid;place-items:center;border-radius:9px;background:var(--accent-soft);color:var(--accent)}.login-icon svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.8}.login-card h2{font-size:24px}.login-card .button{width:100%}.login-foot{margin-top:22px;color:var(--muted);font-size:9px;text-align:center}
`

const stylesClientAccessDrawer = `/* Automatic client access v43: keep exports with the deployed service, never in the configuration editor. */
.client-profile-drawer{border-top:1px solid var(--line);background:var(--surface)}.client-profile-drawer>summary{min-height:40px;display:grid;grid-template-columns:minmax(0,1fr) auto 18px;align-items:center;gap:10px;padding:7px 14px;background:color-mix(in srgb,var(--green-soft) 24%,var(--surface));cursor:pointer}.client-profile-drawer>summary:hover{background:color-mix(in srgb,var(--green-soft) 46%,var(--surface))}.client-profile-drawer>summary span b,.client-profile-drawer>summary span small{display:block}.client-profile-drawer>summary span b{font-size:10px}.client-profile-drawer>summary span small{overflow:hidden;margin-top:1px;color:var(--muted);font-size:8px;text-overflow:ellipsis;white-space:nowrap}.client-profile-drawer>summary>strong{color:var(--green);font-size:8px}.client-profile-drawer>summary>i{color:var(--green);font-style:normal}.client-profile-drawer[open]>summary>i{transform:rotate(45deg)}.client-profile-drawer-body{display:grid;gap:9px;padding:11px 14px 13px;border-top:1px solid var(--line);background:var(--surface-2)}.client-profile-card{min-width:0;padding:11px;border:1px solid var(--line);border-radius:10px;background:var(--surface)}.client-profile-card>header{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:8px}.client-profile-card>header b,.client-profile-card>header small{display:block}.client-profile-card>header b{font-size:10px}.client-profile-card>header small{margin-top:1px;color:var(--muted);font-size:8px}.client-profile-drawer .client-share-control input{width:100%}.client-profile-drawer .client-parameters{grid-template-columns:repeat(3,minmax(0,1fr));margin:0;border-radius:8px}.client-parameter-menu{margin-top:8px;border:1px solid var(--line);border-radius:8px;overflow:hidden}.client-parameter-menu>summary{display:flex;align-items:center;justify-content:space-between;min-height:34px;padding:6px 9px;color:var(--muted);font-size:9px;font-weight:700;cursor:pointer}.client-parameter-menu>summary:hover{background:var(--surface-2)}.client-parameter-menu>summary i{font-size:8px;font-style:normal}.client-parameter-menu[open]>summary{border-bottom:1px solid var(--line)}.client-parameter-menu[open]>summary i{font-size:0}.client-parameter-menu[open]>summary i:after{content:"收起";font-size:8px}.client-profile-note{color:var(--muted);font-size:8px;line-height:1.65}
@media(max-width:820px){.client-profile-drawer>summary{min-height:44px;padding-inline:12px}.client-profile-drawer-body{padding:10px}.client-profile-drawer .client-share-control{flex-wrap:wrap}.client-profile-drawer .client-share-control input{flex-basis:100%;border-radius:7px}.client-profile-drawer .client-share-control button{min-height:38px;flex:1;border-top:0}.client-profile-drawer .client-share-control button:first-of-type{border-left:1px solid var(--line-2);border-radius:7px 0 0 7px}.client-profile-drawer .client-parameters{grid-template-columns:1fr}}
`

const stylesGptImageV45 = `/* GPT Image reference v45: flatter desktop workspace and focused mobile navigation. */
.mobile-account-menu{display:none}.login-shell.compact-login{width:min(420px,calc(100% - 32px));min-height:0;display:block;border:1px solid var(--line);border-radius:16px;background:var(--surface);box-shadow:0 24px 70px -42px rgba(15,18,38,.55)}.compact-login .login-card{display:block;padding:34px}.login-card-brand{justify-content:center;margin-bottom:32px}.login-card-brand .brand-mark{width:48px;height:48px}.login-card-brand strong{font-size:16px}.login-card-brand small{font-size:10px}.compact-login .login-card-head{align-items:center;justify-content:space-between;margin-bottom:22px}.compact-login .login-card-head h1{margin-top:2px;font-size:24px}.compact-login .login-card-head .trust-badge{padding:5px 8px;box-shadow:none}.compact-login .stack-form{gap:16px}.compact-login .login-foot{margin-top:18px}
@media(min-width:821px){.desktop-app{grid-template-columns:68px 232px minmax(0,1fr)}.app-dock{margin:0;padding:12px 7px;border:0;border-radius:0;box-shadow:none}.dock-logo{width:42px;height:42px;border-radius:11px;background:#f4f5f8;box-shadow:none}.dock-nav{margin-top:22px}.dock-nav a,.dock-tools button{width:46px;min-height:46px;border-radius:10px}.dock-nav a.active{background:var(--accent);box-shadow:none}.context-sidebar{margin:0;border:0;border-right:1px solid var(--line);border-radius:0;background:var(--surface);box-shadow:none}.context-brand{min-height:60px}.brand-mark,.context-primary{background:var(--accent);box-shadow:none}.workspace-shell{background:var(--canvas)}.workspace-topbar{height:60px;margin:0;padding:0 22px;border:0;border-bottom:1px solid var(--line);border-radius:0;box-shadow:none}.workspace-main{padding:22px 24px 30px}.button.primary{border-color:var(--accent);background:var(--accent);box-shadow:none}.button.primary:hover{background:var(--accent-2);box-shadow:none}.ops-stats{grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.ops-stats>a,.ops-stats>a:first-child,.ops-stats>a:nth-child(n+2){grid-column:span 1;min-height:108px;display:grid;grid-template-columns:40px minmax(0,1fr);align-items:center;gap:12px;padding:15px;border:1px solid var(--line);border-radius:12px;background:var(--surface);box-shadow:none}.ops-stats>a:hover{transform:none;border-color:color-mix(in srgb,var(--accent) 32%,var(--line));box-shadow:none}.ops-stats>a:first-child .stat-icon{width:40px;height:40px;border-radius:10px}.ops-stats>a:first-child strong,.ops-stats strong{font-size:26px}.workspace-panel,.enrollment-sheet,.machine-workspace,.config-workspace,.live-config-workspace,.task-filter-panel,.task-event-card,.protocol-browser,.recipe-workspace,.node-revision-timeline,.advanced-studio,.inbound-browser,.settings-section{border-color:var(--line);border-radius:12px;box-shadow:none}.settings-section>header,.config-command-head{background:var(--surface)}.settings-savebar{box-shadow:none}.task-load-more{box-shadow:none}}
@media(min-width:821px) and (max-width:1199px){.ops-stats{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:820px){body{padding-bottom:calc(76px + env(safe-area-inset-bottom))}.app-dock{height:64px;display:block;padding:4px}.dock-nav{width:100%;display:grid!important;grid-template-columns:repeat(6,minmax(0,1fr));gap:0;margin:0}.dock-tools{display:none!important}.dock-nav a{width:100%;min-height:54px;margin:0;border-radius:9px}.mobile-account-menu{position:relative;display:block}.mobile-account-menu>summary{width:40px;height:40px;display:grid;place-items:center;border:1px solid var(--line-2);border-radius:9px;background:var(--surface);font-weight:800;letter-spacing:1px;cursor:pointer}.mobile-account-menu>div{position:absolute;z-index:120;right:0;top:46px;width:150px;padding:6px;border:1px solid var(--line);border-radius:11px;background:var(--surface);box-shadow:0 18px 48px -28px rgba(15,18,38,.65)}.mobile-account-menu button{width:100%;min-height:42px;border:0;border-radius:7px;background:transparent;padding:7px 10px;color:var(--ink);text-align:left}.mobile-account-menu button:hover{background:var(--surface-2)}.mobile-account-menu form{margin:0}.workspace-actions{gap:7px}.workspace-actions>.button{padding-inline:9px}.ops-stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.ops-stats>a,.ops-stats>a:first-child,.ops-stats>a:nth-child(n+2){grid-column:span 1;min-height:98px;display:block;padding:13px;border:1px solid var(--line);border-radius:12px;background:var(--surface);box-shadow:none}.ops-stats .stat-icon{display:none}.ops-stats>a:first-child strong,.ops-stats strong{font-size:27px}.ops-stats>a p{margin-top:4px}.login-body{min-height:100vh;padding:18px;background:var(--canvas)}.login-shell.compact-login{width:100%;min-height:0;display:block;border-radius:15px;background:var(--surface)}.compact-login .login-card{position:static;margin:0;padding:28px 22px;border-radius:15px;background:var(--surface)}.login-card-brand{margin-bottom:28px}.compact-login .login-card-head{align-items:flex-start}.compact-login .login-card-head h1{font-size:22px}}

`
